import type { Root } from 'mdast';
import { describe, expect, it } from 'vitest';

import { unifiedRemoveNestedRoots } from '../src/utils/nestedRoots.js';

const text = (value: string) => ({
  type: 'paragraph' as const,
  children: [{ type: 'text' as const, value }],
});

describe('unifiedRemoveNestedRoots', () => {
  it('walks the replaced children array, like upstream unist-util-visit', () => {
    const tree = {
      type: 'root',
      children: [
        { type: 'root', children: [text('first')] },
        { type: 'root', children: [text('second')] },
      ],
    } as unknown as Root;

    unifiedRemoveNestedRoots()(tree);

    expect(tree.children).toEqual([text('first')]);
  });
});
